package br.com.onda;
import java.net.*;import java.util.*;import java.security.*;import java.nio.charset.StandardCharsets;import org.json.*;
/** Public HTTPS audio streams; query tokens are kept, never upgraded from HTTP by guesswork. */
final class RadioStation {
 final String id,name,url,country,codec;final int bitrate;final boolean hls;
 RadioStation(String id,String name,String url,String country,String codec,int bitrate,boolean hls){this.url=stream(url);this.id=id!=null&&id.matches("[A-Za-z0-9_-]{1,100}")?id:key(this.url);this.name=clean(name,"Rádio online",120);this.country=clean(country,"",80);this.codec=clean(codec,"",20);this.bitrate=Math.max(0,Math.min(20000,bitrate));this.hls=hls||this.url.split("\\?",2)[0].toLowerCase(Locale.ROOT).endsWith(".m3u8");}
 static String stream(String raw){try{if(raw==null||raw.length()>8192)throw new Exception();URI u=new URI(raw.trim());String h=u.getHost();if(!"https".equalsIgnoreCase(u.getScheme())||h==null||u.getUserInfo()!=null||u.getFragment()!=null||u.getPort()>65535||u.getPort()==0)throw new Exception();h=h.toLowerCase(Locale.ROOT);if(!h.contains(".")||h.contains(":")||h.matches("[0-9.]+")||h.endsWith(".")||h.endsWith(".local")||h.endsWith(".localhost")||h.endsWith(".internal")||h.endsWith(".lan")||h.endsWith(".test")||h.endsWith(".invalid"))throw new Exception();return u.toASCIIString();}catch(Exception e){throw new IllegalArgumentException("Use um endereço HTTPS direto da transmissão de rádio.");}}
 private static String clean(String s,String fallback,int max){String v=s==null?"":s.replaceAll("[\\p{Cntrl}\\s]+"," ").trim();return v.isEmpty()?fallback:v.substring(0,Math.min(max,v.length()));}
 static String key(String url){try{byte[] hash=MessageDigest.getInstance("SHA-256").digest(url.getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder("manual-");for(int i=0;i<16;i++)out.append(String.format(Locale.ROOT,"%02x",hash[i]&255));return out.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 String detail(){return (country.isEmpty()?"Rádio online":country)+(codec.isEmpty()?"":" • "+codec)+(bitrate>0?" • "+bitrate+" kbps":"")+" • "+RadioData.estimate(bitrate);}
 JSONObject json()throws JSONException{return new JSONObject().put("id",id).put("name",name).put("url",url).put("country",country).put("codec",codec).put("bitrate",bitrate).put("hls",hls);}
 static List<RadioStation> read(String raw,boolean directory)throws JSONException{if(raw==null||directory&&raw.length()>2*1024*1024)throw new JSONException("Lista de rádios inválida");JSONArray a=new JSONArray(raw);ArrayList<RadioStation> result=new ArrayList<>();Set<String> seen=new HashSet<>();for(int i=0;i<a.length();i++)try{JSONObject o=a.getJSONObject(i);String url=directory?o.optString("url_resolved",""):o.optString("url","");if(directory)try{url=stream(url);}catch(IllegalArgumentException bad){url=o.optString("url","");}RadioStation s=new RadioStation(o.optString(directory?"stationuuid":"id"),o.optString("name"),url,o.optString("country"),o.optString("codec"),o.optInt("bitrate"),directory?o.optInt("hls")==1:o.optBoolean("hls"));if(seen.add(s.id))result.add(s);}catch(JSONException|IllegalArgumentException ignored){}return result;}
 static String write(Collection<RadioStation> list){JSONArray a=new JSONArray();for(RadioStation s:list)try{a.put(s.json());}catch(JSONException ignored){}return a.toString();}
}
